/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_status">KCS_StatusId</param>
void updateSalesQuotationTable(KCS_StatusId _status)
{
    KCS_QuotationStatus         quotationStatus;
    AVAQuotationStatusModify    quotationStatusModify;
    SalesQuotationTable         salesQuotationTable = CustQuotationTrans::findRecId(tmpFrmVirtualLines.RecordNo).custQuotationJour().salesQuotationTable();
    salesQuotationTable         sqt;
    Args                        args;

    quotationStatus = KCS_QuotationStatus::find(_status);
    args = new Args();
    args.record(salesQuotationTable);
    quotationStatusModify = AVAQuotationStatusModify::construct(args);
    quotationStatusModify.init();
    quotationStatusModify.parmStatusId(quotationStatus.KCS_StatusId);
    quotationStatusModify.parmReasonId(quotationStatus.KCS_ReasonId);
    quotationStatusModify.parmAltStatusId(quotationStatus.KCS_AltStatusId);
    quotationStatusModify.parmQuotationStatus(quotationStatus.KCS_SalesQuotationStatus);
    quotationStatusModify.parmDecisionDate(quotationStatusModify.parmDecisionDate() == dateNull() ? DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) : quotationStatusModify.parmDecisionDate());
    quotationStatusModify.updateSalesQuotation();

    ttsbegin;
    sqt = salesQuotationTable::find(salesQuotationTable.QuotationId, true);
    if (sqt.RecId)
    {
        sqt.QuotationStatus    = SalesQuotationStatus::Confirmed;
        sqt.doUpdate();
    }
    ttscommit;

}

